// ---- FILL THESE TWO IN --------------------------------------------------
const EXPLEE_KEY     = 'PUT_EXPLEE_KEY_HERE';
const LINKFINDER_KEY = 'PUT_LINKFINDER_KEY_HERE';

// ---- and change this to whatever you want to find -----------------------
const DEFINITION  = 'organisme de formation, centre de formation in France';
const COMPANIES   = 5;          // Explee: first 100 results are free
const SENIORITY   = 'director'; // LinkFinder: which people at each company
const PER_COMPANY = 3;          // 1 credit per person returned, email included

return [{ json: { EXPLEE_KEY, LINKFINDER_KEY, DEFINITION, COMPANIES,
                  SENIORITY, PER_COMPANY } }];

// Pull the domains out of whatever Explee returned. If the shape is not what
// this expects it throws WITH the payload, so you can see it rather than
// getting an empty run.
const j = $input.first().json;
const rows = j.companies || j.results || j.items || j.data || [];
const clean = d => String(d || '').trim().toLowerCase()
  .replace(/^https?:\/\//, '').replace(/^www\./, '').replace(/\/.*$/, '');
const domains = [...new Set(rows
  .map(r => clean(r.domain || r.website || r.company_domain || r.companyWebsite ||
                  r.company_website || r.url))
  .filter(d => d.includes('.')))];

if (!domains.length) {
  throw new Error('No domains found. Top-level keys: ' + Object.keys(j).join(', ') +
    ' | first row: ' + JSON.stringify(rows[0] || j).slice(0, 500));
}
return domains.map(domain => ({ json: { domain } }));

// One credit per person returned, email included in that.
// company_domain_to_employees is async, so post then poll the job here rather
// than with a Wait/If loop.
const cfg = $('Config').first().json;
if (!this.helpers || !this.helpers.httpRequest) {
  throw new Error('This n8n has no this.helpers.httpRequest in Code nodes.');
}
const http = opts => this.helpers.httpRequest(opts);
const sleep = ms => new Promise(r => setTimeout(r, ms));
const API = 'https://api.linkfinderai.com';
const auth = { Authorization: 'Bearer ' + cfg.LINKFINDER_KEY };

const out = [];
for (const { json: { domain } } of $input.all()) {
  let r;
  try {
    r = await http({ method: 'POST', url: API, headers: auth, json: true, body: {
      type: 'company_domain_to_employees', input_data: domain,
      seniority: cfg.SENIORITY, employee_count: cfg.PER_COMPANY } });
  } catch (e) { console.log(domain + ' -> ' + e.message); continue; }

  for (let n = 0; r && r.job_id && !r.result && n < 8; n++) {
    await sleep(8000);
    try {
      r = await http({ method: 'GET', headers: auth, json: true,
        url: r.poll_url || API + '/status/' + r.job_id });
    } catch (e) { console.log(domain + ' poll -> ' + e.message); r = null; }
  }

  const rows = (r && r.result) || [];
  console.log(domain + ': ' + rows.length + ' people');
  for (const p of rows) {
    out.push({ json: {
      domain,
      name: p.name || [p.firstName, p.lastName].filter(Boolean).join(' '),
      title: p.jobTitle || '',
      email: p.email || '',
      linkedin: p.linkedinUrl || '',
      company: p.company || '',
      country: p.country || '',
    } });
  }
  await sleep(1100);
}
if (!out.length) throw new Error('No people at any domain. Check the node logs.');
console.log(out.filter(i => i.json.email).length + ' of ' + out.length + ' have an email');
return out;
